// Provision one subscriber (imsi-208930000000001) into the free5gc DB.
// Document layout follows docker/free5gc/free5gc-dbpython/add_subscribers.py in free5gc-helm@07139fc,
// restricted to a single slice (sst 1 / sd 010203) and a single DNN (internet).
const ueId = "imsi-208930000000001";
const plmn = "20893";
const snssai = { sst: 1, sd: "010203" };
const smPolicy = { sst: 1, sd: "010203" };
const sessionCfg = {
  pduSessionTypes: { defaultSessionType: "IPV4", allowedSessionTypes: ["IPV4"] },
  sscModes: { defaultSscMode: "SSC_MODE_1", allowedSscModes: ["SSC_MODE_1", "SSC_MODE_2", "SSC_MODE_3"] },
  sessionAmbr: { uplink: "200 Mbps", downlink: "100 Mbps" },
  "5gQosProfile": {
    "5qi": 9,
    arp: { priorityLevel: 8, preemptCap: "", preemptVuln: "" },
    priorityLevel: 8,
  },
};

const db = db.getSiblingDB("free5gc");
const data = {
  "subscriptionData.authenticationData.authenticationSubscription": {
    ueId, authenticationMethod: "5G_AKA", authenticationManagementField: "8000",
    sequenceNumber: "16f3b3f70fc2",
    permanentKey: { permanentKeyValue: "8baf473f2f8fd09487cccbd7097c6862", encryptionKey: 0, encryptionAlgorithm: 0 },
    opc: { opcValue: "8e27b6af0e692e750f32667a3b14605d", encryptionKey: 0, encryptionAlgorithm: 0 },
    milenage: { op: { opValue: "", encryptionKey: 0, encryptionAlgorithm: 0 } },
  },
  "subscriptionData.provisionedData.amData": {
    ueId, servingPlmnId: plmn, gpsis: ["msisdn-0900000001"],
    nssai: { defaultSingleNssais: [snssai], singleNssais: [snssai] },
    subscribedUeAmbr: { uplink: "1 Gbps", downlink: "2 Gbps" },
  },
  "subscriptionData.provisionedData.smData": {
    ueId, servingPlmnId: plmn, singleNssai: snssai,
    dnnConfigurations: { internet: sessionCfg },
  },
  "subscriptionData.provisionedData.smfSelectionSubscriptionData": {
    ueId, servingPlmnId: plmn,
    subscribedSnssaiInfos: { "01010203": { dnnInfos: [{ dnn: "internet" }] } },
  },
  "policyData.ues.amData": { ueId, subscCats: ["free5gc"] },
  "policyData.ues.smData": {
    ueId,
    smPolicySnssaiData: {
      "01010203": { snssai: smPolicy, smPolicyDnnData: { internet: { dnn: "internet" } } },
    },
  },
};

for (const [colName, doc] of Object.entries(data)) {
  const col = db.getCollection(colName);
  const r = col.deleteMany({ ueId });
  col.insertOne(doc);
  print(`${colName}: removed ${r.deletedCount}, inserted 1`);
}
print("verify authenticationSubscription:");
printjson(db.getCollection("subscriptionData.authenticationData.authenticationSubscription").find({ ueId }, { _id: 0 }).toArray());

